

CREATE DATABASE IF NOT EXISTS faculty_technology_management;
USE faculty_technology_management;

CREATE TABLE `User` (
                        User_ID INT AUTO_INCREMENT PRIMARY KEY,
                        Username VARCHAR(50) NOT NULL UNIQUE,
                        Password VARCHAR(255) NOT NULL,
                        Role VARCHAR(30) NOT NULL,
                        Email VARCHAR(100) UNIQUE,
                        Fname VARCHAR(50),
                        Lname VARCHAR(50),
                        Profile_pic VARCHAR(255),
                        Phone VARCHAR(20)
);

CREATE TABLE Admin (
                       Admin_ID INT PRIMARY KEY,
                       FOREIGN KEY (Admin_ID) REFERENCES `User`(User_ID)
);

CREATE TABLE Lecturer (
                          Lecturer_ID INT PRIMARY KEY,
                          Department VARCHAR(100),
                          FOREIGN KEY (Lecturer_ID) REFERENCES `User`(User_ID)
);

CREATE TABLE Technical_Officer (
                                   TO_ID INT PRIMARY KEY,
                                   Department VARCHAR(100),
                                   FOREIGN KEY (TO_ID) REFERENCES `User`(User_ID)
);

CREATE TABLE Student (
                         Student_ID INT PRIMARY KEY,
                         TG_num VARCHAR(30) UNIQUE,
                         Batch VARCHAR(20),
                         Department VARCHAR(100),
                         NIC VARCHAR(20),
                         Status VARCHAR(30),
                         Year INT,
                         Semester INT,
                         FOREIGN KEY (Student_ID) REFERENCES `User`(User_ID)
);

CREATE TABLE Course (
                        Course_code VARCHAR(20) PRIMARY KEY,
                        Course_name VARCHAR(150) NOT NULL,
                        Academic_year INT,
                        Semester INT,
                        Theory_credits INT,
                        Practical_credits INT,
                        Theory_hours INT,
                        Practical_hours INT
);

-- Student enrolls in Course (relationship in ER diagram)
CREATE TABLE Enrollment (
                            Enrollment_ID INT AUTO_INCREMENT PRIMARY KEY,
                            Student_ID INT NOT NULL,
                            Course_code VARCHAR(20) NOT NULL,
                            Academic_year INT,
                            Semester INT,
                            FOREIGN KEY (Student_ID) REFERENCES Student(Student_ID),
                            FOREIGN KEY (Course_code) REFERENCES Course(Course_code),
                            UNIQUE (Student_ID, Course_code, Academic_year, Semester)
);

CREATE TABLE Notice (
                        Notice_ID INT AUTO_INCREMENT PRIMARY KEY,
                        Admin_ID INT,
                        Title VARCHAR(150),
                        Content TEXT,
                        Published_date DATE,
                        FOREIGN KEY (Admin_ID) REFERENCES Admin(Admin_ID)
);

CREATE TABLE Course_Material (
                                 Material_ID INT AUTO_INCREMENT PRIMARY KEY,
                                 Course_code VARCHAR(20),
                                 Lecturer_ID INT,
                                 Title VARCHAR(150),
                                 Material_type VARCHAR(50),
                                 File_path VARCHAR(255),
                                 Uploaded_date DATE,
                                 FOREIGN KEY (Course_code) REFERENCES Course(Course_code),
                                 FOREIGN KEY (Lecturer_ID) REFERENCES Lecturer(Lecturer_ID)
);

CREATE TABLE Attendance (
                            Attendance_ID INT AUTO_INCREMENT PRIMARY KEY,
                            Student_ID INT NOT NULL,
                            Course_code VARCHAR(20) NOT NULL,
                            Session_date DATE,
                            Type VARCHAR(20),
                            Is_Present TINYINT(1) NOT NULL DEFAULT 1,
                            FOREIGN KEY (Student_ID) REFERENCES Student(Student_ID),
                            FOREIGN KEY (Course_code) REFERENCES Course(Course_code)
);

CREATE TABLE Medical (
                         Medical_ID INT AUTO_INCREMENT PRIMARY KEY,
                         Student_ID INT NOT NULL,
                         Attendance_ID INT,
                         Submission_date DATE,
                         Start_date DATE,
                         End_date DATE,
                         Reason TEXT,
                         Approval_status VARCHAR(30),
                         Status VARCHAR(30),
                         FOREIGN KEY (Student_ID) REFERENCES Student(Student_ID),
                         FOREIGN KEY (Attendance_ID) REFERENCES Attendance(Attendance_ID)
);

CREATE TABLE Marks (
                       Mark_ID INT AUTO_INCREMENT PRIMARY KEY,
                       Student_ID INT NOT NULL,
                       Course_code VARCHAR(20) NOT NULL,
                       CA_marks DECIMAL(5,2),
                       Final_exam_marks DECIMAL(5,2),
                       Total_marks DECIMAL(5,2),
                       Grade VARCHAR(5),
                       FOREIGN KEY (Student_ID) REFERENCES Student(Student_ID),
                       FOREIGN KEY (Course_code) REFERENCES Course(Course_code)
);

CREATE TABLE GPA (
                     GPA_ID INT AUTO_INCREMENT PRIMARY KEY,
                     Student_ID INT NOT NULL,
                     SGPA DECIMAL(4,2),
                     CGPA DECIMAL(4,2),
                     Semester INT,
                     FOREIGN KEY (Student_ID) REFERENCES Student(Student_ID)
);

CREATE TABLE Timetable (
                           Timetable_ID INT AUTO_INCREMENT PRIMARY KEY,
                           Course_code VARCHAR(20) NOT NULL,
                           Department VARCHAR(100),
                           Day VARCHAR(20),
                           Time_slot VARCHAR(50),
                           FOREIGN KEY (Course_code) REFERENCES Course(Course_code)
);


