-- Medicals for absent sessions (approved and pending examples)
SELECT a.Student_ID, a.Attendance_ID, '2026-09-15', a.Session_date, a.Session_date, 'Medical certificate submitted', 'APPROVED', 'RECORDED'
FROM Attendance a WHERE a.Student_ID = 14 AND a.Course_code = 'ICT2132' AND a.Type = 'THEORY' AND a.Is_Present = 0 ORDER BY a.Session_date LIMIT 1;
SELECT a.Student_ID, a.Attendance_ID, '2026-09-15', a.Session_date, a.Session_date, 'Medical certificate awaiting review', 'PENDING', 'RECORDED'
FROM Attendance a WHERE a.Student_ID = 15 AND a.Course_code = 'ICT2132' AND a.Type = 'PRACTICAL' AND a.Is_Present = 0 ORDER BY a.Session_date LIMIT 1;



