-- Simple verification queries
SELECT Role, COUNT(*) AS Total FROM `User` GROUP BY Role;
SELECT Status, COUNT(*) AS Total FROM Student GROUP BY Status;
SELECT Course_code, Type, COUNT(*) AS Total_Session_Records FROM Attendance GROUP BY Course_code, Type;
-- Attendance % for each student/course/type, with 15 sessions recorded per type
SELECT Student_ID, Course_code, Type, SUM(Is_Present) AS Present, COUNT(*) AS Sessions,
       ROUND(100 * SUM(Is_Present) / COUNT(*), 2) AS Attendance_Percentage
FROM Attendance GROUP BY Student_ID, Course_code, Type;
-- CA eligibility (CA >= 40 only; full eligibility must also evaluate attendance/medical rules)
SELECT Student_ID, Course_code, CA_marks,
       CASE WHEN CA_marks >= 40 THEN 'CA_ELIGIBLE' ELSE 'CA_NOT_ELIGIBLE' END AS CA_Status
FROM Marks;
